insert into public.tenants (slug, mode, timezone, profile) values ('kolyada', 'preview', 'Europe/Minsk', '{"name":"Коляда","shortName":"Коляда","kind":"СТО · Минск","tagline":"СТО на Тиражной: Citroën, Peugeot, Renault и коммерческий транспорт","description":"Специализированный сервис французских автомобилей: диагностика, ГРМ, ходовая, обслуживание фильтра FAP. Wi-Fi и парковка. Демо-версия сайта для СТО: цены взяты из карточки на картах и могли измениться, часы примерные — владелец меняет всё в кабинете.","address":"г. Минск, ул. Тиражная, 123","phone":"+375 29 640-70-60","accent":"#E8833A","cards":[{"title":"Французские авто","text":"Citroën, Peugeot, Renault — знаем их изнутри."},{"title":"Смета заранее","text":"Согласуем работы и цену до ремонта."},{"title":"Оплата картой","text":"Наличные, карта или безнал."}],"booking":{"bufferMin":10,"stepMin":30,"leadMin":60,"cancelHours":3,"horizonDays":30},"media":{"hero":"/t/kolyada/media/hero.svg","logo":"/t/kolyada/media/logo.svg"}}'::jsonb)
